REVOKE EXECUTE ON FUNCTION public.admin_platform_metrics() FROM authenticated; GRANT EXECUTE ON FUNCTION public.admin_platform_metrics() TO service_role;
CREATE OR REPLACE FUNCTION public.admin_platform_metrics() RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('accounts',(SELECT count(*) FROM public.profiles WHERE user_id IS NOT NULL),'new_accounts_30d',(SELECT count(*) FROM public.profiles WHERE user_id IS NOT NULL AND created_at>now()-interval '30 days'),'museums',(SELECT count(*) FROM public.museums),'public_museums',(SELECT count(*) FROM public.museums WHERE is_public),'objects',(SELECT count(*) FROM public.objects),'open_errors',(SELECT count(*) FROM public.app_errors WHERE NOT resolved),'errors_7d',(SELECT count(*) FROM public.app_errors WHERE created_at>now()-interval '7 days'),'open_tasks',(SELECT count(*) FROM public.dev_tasks WHERE payload->>'status'<>'done'),'plan_interests',(SELECT coalesce(jsonb_object_agg(plan,n),'{}'::jsonb) FROM (SELECT plan,count(*) n FROM public.plan_interests GROUP BY plan) s),'active_subscriptions',(SELECT count(*) FROM public.subscriptions WHERE status='active' AND plan<>'free'),'mrr_by_currency',(SELECT coalesce(jsonb_object_agg(currency,amount),'{}'::jsonb) FROM (SELECT currency,sum(monthly_amount_minor) amount FROM public.subscriptions WHERE status='active' AND plan<>'free' GROUP BY currency) s),'countries',(SELECT coalesce(jsonb_object_agg(country,n),'{}'::jsonb) FROM (SELECT country,count(*) n FROM public.profiles WHERE user_id IS NOT NULL AND country IS NOT NULL GROUP BY country) s)) $$;
DROP FUNCTION public.report_app_error(text,text,text);
CREATE FUNCTION public.report_app_error(reporter uuid,error_category text,error_path text,error_fingerprint text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF reporter IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF; IF error_category NOT IN ('runtime','unhandled_rejection','operation','route') OR error_path !~ '^/[a-zA-Z0-9/_.$-]{0,200}$' OR error_fingerprint !~ '^[a-f0-9]{8,64}$' THEN RAISE EXCEPTION 'Invalid diagnostic'; END IF; PERFORM pg_advisory_xact_lock(hashtext(reporter::text)); IF (SELECT count(*) FROM public.app_errors WHERE user_id=reporter AND created_at>now()-interval '1 hour')>=20 THEN RETURN false; END IF; IF EXISTS(SELECT 1 FROM public.app_errors WHERE user_id=reporter AND fingerprint=error_fingerprint AND created_at>now()-interval '5 minutes') THEN RETURN false; END IF; INSERT INTO public.app_errors(user_id,category,path,fingerprint) VALUES(reporter,error_category,error_path,error_fingerprint); RETURN true; END $$;
REVOKE ALL ON FUNCTION public.report_app_error(uuid,text,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.report_app_error(uuid,text,text,text) TO service_role;